import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";
import sorsuLogo from "../assets/sorsu-logo.png";

const API_URL = "http://localhost:5000";

const THEME = {
  primary: "#B11226",
  background: "#F8F9FA",
  white: "#FFFFFF",
};

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [selected, setSelected] = useState({});
  const [alreadyVotedPositions, setAlreadyVotedPositions] = useState({});
  const [showModal, setShowModal] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [modalType, setModalType] = useState("confirm");

  useEffect(() => {
    const fetchCandidatesAndVotes = async () => {
      try {
        setLoading(true);

        // Fetch candidates
        const resCandidates = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(resCandidates.data);

        // Fetch previous votes
        if (auth?.token) {
          try {
            const resVotes = await axios.get(`${API_URL}/api/vote/my`, {
              headers: { Authorization: `Bearer ${auth.token}` },
            });
            const selectedVotes = {};
            const votedPositions = {};
            resVotes.data.forEach((vote) => {
              selectedVotes[vote.position] = vote.candidateId;
              votedPositions[vote.position] = true;
            });
            setSelected(selectedVotes);
            setAlreadyVotedPositions(votedPositions);
          } catch (err) {
            console.warn(
              "Failed to load previous votes. Candidates loaded anyway.",
              err.response || err.message
            );
          }
        }
      } catch (err) {
        console.error("Failed to fetch candidates:", err.response || err.message);
        setModalMessage("Failed to load candidates. Please check your backend.");
        setModalType("error");
        setShowModal(true);
      } finally {
        setLoading(false);
      }
    };

    fetchCandidatesAndVotes();
  }, [auth]);

  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, candidate) => {
      const position = candidate.candidacy;
      if (!groups[position]) groups[position] = [];
      groups[position].push(candidate);
      return groups;
    }, {});
  }, [candidates]);

  const handleSelect = (position, candidateId) => {
    if (alreadyVotedPositions[position]) return;
    setSelected((prev) => ({ ...prev, [position]: candidateId }));
  };

  const handleCastVote = () => {
    if (Object.keys(selected).length === 0) {
      setModalType("error");
      setModalMessage("Please select a candidate before casting vote.");
      setShowModal(true);
      return;
    }
    setModalType("confirm");
    setModalMessage("Are you sure you want to cast your vote?");
    setShowModal(true);
  };

  const confirmVote = async () => {
    try {
      setSubmitting(true);
      await axios.post(
        `${API_URL}/api/vote/batch`,
        { candidateIds: Object.values(selected) },
        { headers: { Authorization: `Bearer ${auth?.token}` } }
      );
      setModalType("success");
      setModalMessage("Your vote has been successfully recorded.");
    } catch (err) {
      console.error("Failed to cast vote:", err.response || err.message);
      setModalType("error");
      setModalMessage("Vote failed or you may have already voted.");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <div style={{ padding: 50 }}>Loading Ballot...</div>;

  return (
    <div style={{ backgroundColor: THEME.background, minHeight: "100vh" }}>
      {/* HEADER */}
      <div
        style={{
          backgroundColor: THEME.primary,
          padding: "20px 40px",
          display: "flex",
          alignItems: "center",
        }}
      >
        <img src={sorsuLogo} alt="SorSU Logo" style={{ height: 70, marginRight: 20 }} />
        <div style={{ color: "white" }}>
          <h2 style={{ margin: 0 }}>Ballot</h2>
          <p style={{ margin: 0 }}>Official Student Election Portal 2026</p>
        </div>
      </div>

      {/* CONTENT */}
      <div style={{ padding: 60, maxWidth: 1300, margin: "auto" }}>
        {Object.entries(groupedCandidates).map(([position, list]) => (
          <div key={position} style={{ marginBottom: 60 }}>
            <h2
              style={{
                marginBottom: 30,
                color: THEME.primary,
                borderLeft: `6px solid ${THEME.primary}`,
                paddingLeft: 15,
              }}
            >
              {position}
            </h2>

            <div
              style={{
                display: "flex",
                gap: 20,
                flexWrap: "nowrap",
                overflowX: "auto",
                paddingBottom: 10,
              }}
            >
              {list.map((candidate) => {
                const isSelected = selected[position] === candidate._id;
                const isLocked = alreadyVotedPositions[position];

                return (
                  <div
                    key={candidate._id}
                    onClick={() => handleSelect(position, candidate._id)}
                    style={{
                      width: 240,
                      flex: "0 0 auto",
                      backgroundColor: THEME.white,
                      borderRadius: 15,
                      padding: 20,
                      cursor: isLocked ? "not-allowed" : "pointer",
                      border: isSelected
                        ? `4px solid ${THEME.primary}`
                        : "2px solid transparent",
                      boxShadow: isSelected
                        ? "0 15px 30px rgba(177,18,38,0.3)"
                        : "0 10px 25px rgba(0,0,0,0.05)",
                      position: "relative",
                      transition: "0.3s",
                    }}
                  >
                    {candidate.image && (
                      <img
                        src={`${API_URL}/uploads/${candidate.image}`}
                        alt=""
                        style={{
                          width: "100%",
                          height: 180,
                          objectFit: "cover",
                          borderRadius: 10,
                          marginBottom: 12,
                        }}
                      />
                    )}
                    <h3>{candidate.firstName} {candidate.lastName}</h3>
                    <p>{candidate.yearLevel} - {candidate.block}</p>
                    <p>Partylist: {candidate.partylist || "Independent"}</p>

                    {/* Overlay if already voted */}
                    {isLocked && (
                      <div style={{
                        position: "absolute",
                        top: 0,
                        left: 0,
                        width: "100%",
                        height: "100%",
                        backgroundColor: "rgba(0,0,0,0.3)",
                        borderRadius: 15,
                        display: "flex",
                        justifyContent: "center",
                        alignItems: "center",
                        color: "#fff",
                        fontWeight: "bold",
                        fontSize: 16,
                      }}>
                        Already Voted
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {/* CAST VOTE BUTTON */}
        <div style={{ textAlign: "center", marginTop: 40 }}>
          <button
            onClick={handleCastVote}
            disabled={submitting}
            style={{
              padding: "15px 40px",
              fontSize: 18,
              fontWeight: "bold",
              backgroundColor: THEME.primary,
              color: "white",
              border: "none",
              borderRadius: 10,
              cursor: "pointer",
            }}
          >
            Cast Vote
          </button>
        </div>
      </div>

      {/* MODAL */}
      {showModal && (
        <div style={modalStyles.overlay}>
          <div style={modalStyles.modal}>
            <h3>
              {modalType === "confirm"
                ? "Confirm Vote"
                : modalType === "success"
                ? "Success"
                : "Error"}
            </h3>
            <p style={{ marginBottom: 20 }}>{modalMessage}</p>

            {modalType === "confirm" ? (
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <button style={modalStyles.cancel} onClick={() => setShowModal(false)}>
                  Cancel
                </button>
                <button style={modalStyles.confirm} onClick={confirmVote}>
                  Confirm
                </button>
              </div>
            ) : (
              <button style={modalStyles.confirm} onClick={() => setShowModal(false)}>
                OK
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const modalStyles = {
  overlay: {
    position: "fixed",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    backgroundColor: "rgba(0,0,0,0.6)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },
  modal: {
    width: 380,
    backgroundColor: "#fff",
    padding: 30,
    borderRadius: 12,
    textAlign: "center",
  },
  cancel: {
    padding: "10px 20px",
    backgroundColor: "#ccc",
    border: "none",
    borderRadius: 6,
    cursor: "pointer",
  },
  confirm: {
    padding: "10px 20px",
    backgroundColor: "#B11226",
    color: "#fff",
    border: "none",
    borderRadius: 6,
    cursor: "pointer",
  },
};

export default VotingPage;
